// Job fit score (packages/core/fit.js), a port of the Autonomous Job Kit's
// rank_jobs.py. The parity tables compare it with what the Python gives for the
// same made-up inputs (tests/fixtures/jobkit/fit: inputs.json, expected.json,
// regenerated by gen_parity.py), then the behaviour the kit documents is
// checked case by case.
const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const F = require('../../packages/core/fit');

const DIR = path.join(__dirname, '..', 'fixtures', 'jobkit', 'fit');
const INPUTS = require(path.join(DIR, 'inputs.json'));
const EXPECTED = require(path.join(DIR, 'expected.json'));
const TODAY = INPUTS.today;
const S = INPUTS.searches;

function register(rows) {
  const out = new Map();
  for (const r of rows) {
    const k = F.sponsorNorm(r.name);
    if (!out.has(k)) out.set(k, []);
    out.get(k).push(r);
  }
  return out;
}

// ---------- parity with rank_jobs.py ----------

test('parity: score() gives what rank_jobs.score() gives for every posting', () => {
  assert.ok(INPUTS.cases.length >= 12);
  assert.equal(EXPECTED.cases.length, INPUTS.cases.length);
  INPUTS.cases.forEach((c, i) => {
    const options = { today: TODAY };
    if (c.sponsors) options.sponsors = register(INPUTS.registers[c.sponsors]);
    const got = F.score(c.posting, INPUTS.masters[c.master], S[c.search], options);
    const want = EXPECTED.cases[i];
    assert.equal(want.name, c.name);
    const { reasons, ...comparable } = got;
    assert.deepEqual(comparable, want.result, c.name);
    assert.equal(reasons.join('; '), got.why);
  });
});

test('parity: the parity table covers the score range, every place and the flag kinds', () => {
  const results = EXPECTED.cases.map((c) => c.result);
  const places = new Set(results.map((r) => r.place));
  for (const p of ['local', 'region', 'remote-country', 'country', 'remote', null]) assert.ok(places.has(p), `place ${p}`);
  const scores = results.map((r) => r.score);
  assert.ok(Math.min(...scores) < 40 && Math.max(...scores) === 100);
  const flags = results.flatMap((r) => r.flags).join('\n');
  for (const f of ['citizenship', 'U.S. work authorization', 'no visa sponsorship', 'visa sponsorship mentioned', 'UK right to work',
    'security clearance', 'P.Eng. required', 'co-op or student only', 'French required', "driver's licence", 'temporary or contract',
    'is on the UK sponsor register', 'a similar name is on', 'not found on the UK sponsor register', "couldn't check the UK sponsor register",
    'TEER 1', 'CEC counts TEER 0-3', 'no NOC code', 'part-time', 'below your minimum', 'no yearly salary', 'not in your eligibleCodes']) {
    assert.ok(flags.includes(f), f);
  }
});

test('parity: the helper functions match the Python on edge cases', () => {
  const f = INPUTS.functions;
  const want = EXPECTED.functions;
  assert.deepEqual(f.placeFit.map(([k, loc]) => F.placeFit(loc, S[k])), want.placeFit);
  assert.deepEqual(f.yearsRequired.map(F.yearsRequired), want.yearsRequired);
  assert.deepEqual(f.salaryMax.map(F.salaryMax), want.salaryMax);
  assert.deepEqual(f.termsIn.map((s) => [...F.termsIn(s)].sort()), want.termsIn);
  assert.deepEqual(f.textOf.map(F.textOf), want.textOf);
  assert.deepEqual(f.bestTrack.map(([k, t]) => { const b = F.bestTrack(t, S[k]); return [b.track, b.priority]; }), want.bestTrack);
  assert.deepEqual(f.excluded.map(([k, t]) => F.excluded(t, S[k])), want.excluded);
  assert.deepEqual(f.dates.map((s) => F._internals.isoDay(Array.from(s).slice(0, 10).join(''))), want.dates);
  assert.deepEqual(f.sponsorNorm.map(F.sponsorNorm), want.sponsorNorm);
});

// ---------- the behaviour rank_jobs.py documents ----------

const posting = (over = {}) => ({
  role: 'Data Analyst', company: 'Acme', location: 'Halifax, NS', posted: '2026-11-15',
  description: 'Python, SQL, Excel and Tableau. 2 years of experience.', ...over,
});

test('weights: title by track priority, skills share, location, experience and recency add up to the score', () => {
  const many = 'Python, SQL, Excel, Tableau, Power BI, statistics, data cleaning, dashboards. 2 years of experience.';
  const r = F.score(posting({ description: many }), many, S.ca, { today: TODAY });
  assert.deepEqual(r.parts, { title: 30, skills: 30, location: 12, experience: 20, recency: 8 });
  assert.equal(r.score, 100);
  // 4 of 4 skills: 30 * min(1, 4 / 5.5 * 1.2) = 26.2 -> 26
  assert.equal(F.score(posting(), 'python sql excel tableau', S.ca, { today: TODAY }).parts.skills, 26);
  // Python's round(): 30 * 0.75 = 22.5 -> 22 and 30 * 0.25 = 7.5 -> 8 (halves go to the even number)
  assert.equal(F.score(posting({ role: 'Data Scientist' }), '', S.ca_path, { today: TODAY }).parts.title, 22);
  assert.equal(F.score(posting({ role: 'Customer Support Agent' }), '', S.ca_path, { today: TODAY }).parts.title, 8);
  assert.equal(F._internals.pyRound(2.5), 2);
  assert.equal(F._internals.pyRound(3.5), 4);
  assert.equal(F._internals.pyRound(-0.5), 0);
});

test('skills: "3 of 3" counts for less than "12 of 13", weak words never count, too few skills give 13', () => {
  const three = F.score(posting({ description: 'Python, SQL, Tableau.' }), 'python sql tableau', S.ca, { today: TODAY });
  assert.equal(three.parts.skills, 24); // 30 * min(1, 3 / 4.5 * 1.2)
  const weak = F.score(posting({ description: 'Word, policy, API, documentation, reporting and Python.' }), 'python', S.ca, { today: TODAY });
  assert.equal(weak.parts.skills, 13);
  assert.match(weak.why, /skills unknown \(short or no description\)/);
  // Gaps are posting skills missing from the master: shown, never added to a resume
  const r = F.score(posting({ description: 'Python, SQL, Snowflake, dbt.' }), 'Python and SQL', S.ca, { today: TODAY });
  assert.deepEqual(r.matchedSkills, ['python', 'sql']);
  assert.deepEqual(r.gaps, ['dbt', 'snowflake']);
});

test('termsIn: whole words only, spelling variants once, extra skills from search.json', () => {
  assert.deepEqual([...F.termsIn('order management at a reit')], []); // "der" in "order", "eit" in "reit"
  assert.deepEqual([...F.termsIn('Energy modeling and energy modelling')], ['energy modelling']);
  assert.deepEqual([...F.termsIn('REST APIs and KPIs on dashboards')].sort(), ['api', 'dashboard', 'kpi', 'rest api']);
  assert.deepEqual([...F.termsIn('C++, C#, Node.js')].sort(), ['c#', 'c++', 'node.js']);
  assert.deepEqual([...F.termsIn('Figma and QuickBooks', [' Figma ', 'quickbooks', 'python'])].sort(), ['figma', 'quickbooks']);
  assert.ok(F.VOCAB.includes('power bi') && Object.isFrozen(F.VOCAB));
  const r = F.score(posting({ description: 'Alteryx, Looker Studio, SQL, Excel.' }), 'Alteryx and SQL', S.ca, { today: TODAY });
  assert.deepEqual(r.matchedSkills, ['alteryx', 'sql']);
  assert.deepEqual(r.gaps, ['excel', 'looker', 'looker studio']); // "looker" is in VOCAB too
});

test('yearsRequired: the fewest years asked, dates ignored, more than 20 ignored', () => {
  assert.equal(F.yearsRequired('3-5 years of relevant experience'), 3);
  assert.equal(F.yearsRequired('Minimum of 2 years’ experience; 5+ years of experience preferred'), 2);
  assert.equal(F.yearsRequired('Posted: 2026-09-01 8+ years of experience'), 8);
  assert.equal(F.yearsRequired('25 years of experience'), null);
  assert.equal(F.yearsRequired('two years of experience'), null);
  assert.equal(F.yearsRequired('3 years expérience'), null); // Python's \b is Unicode-aware: "exp" + "é" is one word
  assert.equal(F.yearsRequired('٣ years of experience'), 3); // Python's \d and int() read any decimal digit
  const exp = (description, role = 'Data Analyst') => F.score(posting({ role, description }), '', S.ca, { today: TODAY }).parts.experience;
  assert.deepEqual(['2', '3', '4', '5', '6'].map((n) => exp(`${n} years of experience`)), [20, 15, 8, 4, 0]);
  assert.equal(exp('No years stated.'), 14);
  assert.equal(exp('No years stated.', 'Junior Data Analyst'), 20);
});

test('recency: 3, 7, 14 and 30 day steps, 3 points when the date is missing or unreadable', () => {
  const rec = (posted) => F.score(posting({ posted }), '', S.ca, { today: TODAY }).parts.recency;
  assert.deepEqual(['2026-11-13', '2026-11-09', '2026-11-02', '2026-10-17', '2026-10-16'].map(rec), [8, 6, 4, 2, 0]);
  assert.deepEqual(['', null, 'yesterday', '2026-02-30', '2026-11-1'].map(rec), [3, 3, 3, 3, 3]);
  assert.equal(rec('2026-11-20'), 8); // a future date is new
  assert.equal(rec('2026-W46-1'), 6); // ISO week dates and 20261109 work, as in Python 3.11+
  assert.equal(rec('20261109'), 6);
  assert.equal(F.score(posting({ posted: '2026-11-14' }), '', S.ca, { today: new Date(2026, 10, 16) }).parts.recency, 8);
  assert.throws(() => F.score(posting(), '', S.ca, { today: 'soon' }), /today must be an ISO date/);
});

test('placeFit: near home > region > remote in the country > elsewhere in it > remote with no country', () => {
  assert.equal(F.placeFit('Dartmouth, Nova Scotia', S.ca), 'local');
  assert.equal(F.placeFit('Truro, NS', S.ca), 'region');
  assert.equal(F.placeFit('Remote - Canada', S.ca), 'remote-country');
  assert.equal(F.placeFit('Toronto, ON', S.ca), 'country');
  assert.equal(F.placeFit('Remote', S.ca), 'remote');
  // "Hybrid" or "Remote - Colombia" alone is not in the country; several places count by the best one
  assert.equal(F.placeFit('Hybrid', S.ca), null);
  assert.equal(F.placeFit('Remote - Colombia', S.ca), null);
  assert.equal(F.placeFit('Remote, Canada; Remote, United States', S.ca), 'remote-country');
  // ", CA" is California for a US search; "Richmond Hill" isn't "Richmond"
  assert.equal(F.placeFit('San Jose, CA', S.us), 'country');
  assert.equal(F.placeFit('Toronto, ON', S.us), null);
  assert.equal(F.placeFit('Richmond Hill, ON', S.energy_bc), 'country');
  assert.equal(F.placeFit('Richmond, BC', S.energy_bc), 'local');
  assert.equal(F.placeFit('Croydon, London', S.uk), 'local');
  assert.equal(F.placeFit('Croydon', S.uk), null); // a local place alone doesn't show the country
  assert.equal(F.placeFit('Edinburgh, Scotland', S.uk), 'country');
  // No country in search.json means Canada
  assert.equal(F.countryCode({}), 'CA');
  assert.equal(F.countryCode({ country: ' U.S. ' }), 'US');
  assert.equal(F.countryCode({ country: 'Wales' }), 'GB');
  assert.equal(F.countryCode({ country: 'France' }), 'CA');
  const r = F.score(posting({ location: 'Berlin, Germany' }), '', S.ca, { today: TODAY });
  assert.equal(r.parts.location, 0);
  assert.match(r.why, /outside Canada/);
});

test('salaryMax: the highest yearly amount, hourly pay skipped', () => {
  assert.equal(F.salaryMax('£38,000 - £45,000'), 45000);
  assert.equal(F.salaryMax('$65k-$80k'), 80000);
  assert.equal(F.salaryMax('$25 per hour'), null);
  assert.equal(F.salaryMax('$85/hr or $120,000/yr'), 120000);
  assert.equal(F.salaryMax('$5,000,000'), null);
  assert.equal(F.salaryMax('$100,000 a month'), null);
});

test('bestTrack and excluded: whole words in the title, best priority wins, missing priority is 0.5', () => {
  assert.deepEqual(F.bestTrack('Junior Data Analyst', S.ca), { track: 'data', priority: 1 });
  assert.deepEqual(F.bestTrack('Mechanical Engineer', S.energy_bc), { track: 'eng', priority: 0.5 });
  assert.deepEqual(F.bestTrack('Energy Engineer (EIT)', S.energy_bc), { track: 'energy', priority: 1 });
  assert.deepEqual(F.bestTrack('Data Analyst', {}), { track: null, priority: 0 });
  assert.equal(F.excluded('Sr. Data Analyst', S.ca), 'sr.');
  assert.equal(F.excluded('Staff Accountant', S.ca), 'staff ');
  assert.equal(F.excluded('Leadership Program Analyst', S.ca), null);
  assert.equal(F.excluded('Senior Data Analyst', {}), null);
});

test('minimal search objects: no crash, no title points without tracks, Canada by default', () => {
  for (const search of [{}, null, undefined, { country: 'United Kingdom' }, { tracks: {} }, { tracks: { x: null } }, { pathway: 'x' }]) {
    const r = F.score(posting(), 'Python SQL', search, { today: TODAY });
    assert.equal(r.parts.title, 0);
    assert.equal(r.track, null);
    assert.match(r.why, /^title outside your tracks/);
  }
  const r = F.score(posting(), 'Python SQL', {}, { today: TODAY });
  assert.equal(r.place, 'country'); // Halifax is in Canada, but there are no local places or province
  assert.equal(r.score, 0 + 13 + 5 + 20 + 8);
  const bare = F.score({}, '', {}, { today: TODAY });
  assert.deepEqual(bare.parts, { title: 0, skills: 13, location: 0, experience: 14, recency: 3 });
  assert.deepEqual(bare.flags, []);
  assert.deepEqual(F.score({ title: 'Data Analyst' }, null, S.ca, { today: TODAY }).track, 'data'); // "title" works as well as "role"
});

test('flags: quoted with context, co-op once, never change the score', () => {
  const desc = 'Python, SQL, Excel. Must be currently enrolled in a co-op program. Security clearance required.';
  const r = F.score(posting({ role: 'Data Analyst Co-op', description: desc }), 'python sql excel', S.ca, { today: TODAY });
  assert.equal(r.flags.length, 2);
  assert.match(r.flags[0], /^co-op or student only: "co-op" in the title/);
  assert.match(r.flags[1], /^security clearance: "\.\.\..*security clearance required\.\.\.\."$/);
  const plain = F.score(posting({ role: 'Data Analyst Co-op', description: 'Python, SQL, Excel.' }), 'python sql excel', S.ca, { today: TODAY });
  assert.equal(plain.score, r.score);
  // Snippets count characters as Python does (an emoji is one character)
  const emoji = F.score(posting({ description: `${'🚀'.repeat(100)} Security clearance needed.` }), '', S.ca, { today: TODAY });
  assert.equal(emoji.flags[0], `security clearance: "...${'🚀'.repeat(79)} security clearance needed...."`);
});

test('pathway: UK sponsor register as a Map, a Set, a function, or not loaded', () => {
  const p = posting({ company: 'Acme Analytics Ltd', location: 'London', description: 'Salary £40,000. SQL.' });
  const flag = (sponsors) => F.score(p, '', S.uk, { today: TODAY, sponsors }).flags.find((f) => f.includes('sponsor register'));
  const reg = register(INPUTS.registers.main);
  assert.equal(flag(reg), 'pathway: Acme Analytics Ltd is on the UK sponsor register (Global Business Mobility: Senior or Specialist Worker, Skilled Worker)');
  assert.equal(flag(Object.fromEntries(reg)), flag(reg));
  assert.equal(flag(new Set(['acme analytics'])), 'pathway: Acme Analytics Ltd is on the UK sponsor register');
  assert.equal(flag(new Set(['acme analytics software'])), 'pathway: a similar name is on the UK sponsor register (acme analytics software): check it is this employer');
  assert.equal(flag(() => false), 'pathway: Acme Analytics Ltd not found on the UK sponsor register (it may sponsor under another legal name: check)');
  assert.equal(flag((name) => name === 'Acme Analytics Ltd'), 'pathway: Acme Analytics Ltd is on the UK sponsor register');
  assert.equal(flag(undefined), `pathway: couldn't check the UK sponsor register (${F.NO_REGISTER})`);
  assert.equal(flag('register download failed'), "pathway: couldn't check the UK sponsor register (register download failed)");
  // Only for a UK search, a sponsorship pathway and a named company
  assert.equal(F.score({ ...p, company: '' }, '', S.uk, { today: TODAY }).flags.some((f) => f.includes('sponsor register')), false);
  assert.equal(F.score(p, '', S.us, { today: TODAY }).flags.some((f) => f.includes('sponsor register')), false);
  assert.equal(F.sponsorCheck('Acme', reg).status, 'possible'); // "acme analytics" starts with "acme"
  assert.deepEqual(F.sponsorCheck('Acm', reg), { company: 'Acm', status: 'not found', entries: [] }); // under 4 letters: no near match
});

test('pathway: Canadian NOC and TEER, pay below the minimum, eligible codes', () => {
  const desc = 'NOC 2021 code 64409. Salary $45,000 per year.';
  assert.deepEqual(F.pathwayFlags({}, F.textOf(desc), S.ca_path), [
    'pathway: NOC 64409 is TEER 4; CEC counts TEER 0-3 work only (from the posting; confirm on the NOC site)',
    'pathway: posted pay tops out at 45,000, below your minimum of 50,000 (search.json pathway.minSalary)',
    'pathway: NOC 64409 is not in your eligibleCodes list',
  ]);
  assert.deepEqual(F.pathwayFlags({}, 'noc 21211, full-time', S.ca_path), ['pathway: NOC 21211 is TEER 1 (from the posting; confirm on the NOC site)']);
  assert.deepEqual(F.pathwayFlags({}, 'noc 21211', S.ca), []); // pathway type "none"
  assert.deepEqual(F.pathwayFlags({}, 'noc 21211', {}), []);
});

test('scam warnings come from options.redFlags and keep the Python wording', () => {
  const seen = [];
  const redFlags = (text, opts) => { seen.push([text, opts]); return [{ flag: 'asks you to pay', quote: 'Pay a $50 training fee.' }]; };
  const p = posting({ description: 'Pay a $50 training fee.', url: 'https://example.com/j/1' });
  const r = F.score(p, '', S.ca, { today: TODAY, redFlags });
  assert.equal(r.flags.at(-1), 'scam warning: asks you to pay: "Pay a $50 training fee."');
  assert.deepEqual(seen, [['Pay a $50 training fee.', { url: 'https://example.com/j/1', company: 'Acme', role: 'Data Analyst' }]]);
  assert.equal(F.score(p, '', S.ca, { today: TODAY }).flags.length, 0);
});

test('textOf: HTML entities (twice), tags and LaTeX commands, lower case, single spaces', () => {
  assert.equal(F.textOf('<p>Hello &amp;amp; welcome</p>'), ' hello & welcome ');
  assert.equal(F.textOf('Caf&eacute; &copy2026 AT&T'), 'café ©2026 at&t');
  assert.equal(F.textOf('\\textbf{Python} \\& SQL 50\\%'), ' {python} & sql 50%');
  assert.equal(F.textOf(null), '');
});
